import crypto from 'node:crypto';
export const id=n=>`b2960000-0000-4000-8000-${String(n).padStart(12,'0')}`;
export const tid=id(1),eid=id(2),player=id(3),capturer=id(4),reviewer=id(5),gid=id(6),ppgid=id(7);
export const capability=(actor,official=false)=>({kind:'synthetic-mixed-18-v2',tournamentId:tid,eventId:eid,actorId:actor,participantCount:18,digitalCount:6,paperCount:12,matchCount:108,isDigitalParticipant:actor===player,isOfficial:official,sourceCurrent:true,tournamentOpen:true,eventStarted:true,officialIdentityConfirmed:official});
export const own=()=>({kind:'own-synthetic-mixed-hybrid-v1',gameId:gid,eventId:eid,tournamentId:tid,artifactId:id(10),gameVersion:2,notice:'Your opponent is fictional. Acknowledge only your own entry; this is not independent human play.',scriptedWinnerSide:'a',scriptedSpreadPoints:20,digitalSubmissionId:id(11),digitalWinnerSide:'a',digitalMargin:20,acknowledged:false,authoritative:false});
export const games=[{gameId:gid,eventId:eid,eventName:'TEST ONLY local Main',gameNumber:1,matchInstance:1,state:'submitted',playerSide:'a',playerName:'Fictional Digital A',playerTableSeat:'A-1',playerVerificationId:'A-1',opponentName:'Fictional Paper B',opponentTableSeat:'A-2',opponentVerificationId:'A-2',ownSubmitted:true,ownConfirmed:false,canConfirm:false,progressionStatus:'current',nextAction:'wait_opponent_entry'}];
export function artifact(gameId=ppgid,pairing='PP'){
 const artifactId=gameId===ppgid?id(12):id(10),text=JSON.stringify({schema:'synthetic-mixed-paper-v1',tournamentId:tid,eventId:eid,gameId,pairing,sideA:id(20),sideB:id(21),digitalParticipantId:pairing==='PP'?null:id(20),winnerSide:'a',spreadPoints:20,physicalOriginal:false,fictionalOpponentPlayed:false,independentHumanPlayClaimed:false}),sha256=crypto.createHash('sha256').update(text).digest('hex');
 return{artifactId,gameId,eventId:eid,pairing,expectedGameVersion:pairing==='PP'?1:2,text,sha256,sideAReference:`SYNTHETIC-MIXED-v1:${artifactId}:a:${sha256}`,sideBReference:`SYNTHETIC-MIXED-v1:${artifactId}:b:${sha256}`,playerAttested:pairing==='PD'};
}
export const paperCandidate=()=>({gameId:ppgid,eventId:eid,eventName:'TEST ONLY Main',gameNumber:1,gameVersion:1,sideA:{displayName:'Fictional Paper C',verificationId:'B-1',profileLinked:false},sideB:{displayName:'Fictional Paper D',verificationId:'B-2',profileLinked:false}});
export function official(actor,phase='capture',pairing='PP'){
 const art=artifact(pairing==='PP'?ppgid:gid,pairing),p=paperCandidate(),hybrid={gameId:gid,eventId:eid,eventName:'TEST ONLY Main',gameNumber:1,gameVersion:2,digitalSubmissionId:id(11),digitalWinnerSide:'a',digitalMargin:20,digitalSide:'a',digitalPlayerName:'Fictional Digital A',paperPlayerName:'Fictional Paper B',paperVerificationId:'A-2'};
 const paperReview={...p},hybridReview={...hybrid};delete paperReview.eventId;delete hybridReview.eventId;
 return{kind:'synthetic-mixed-official-v1',capability:capability(actor,true),notice:'Fictional paper evidence. No physical original or independent human play is claimed.',artifacts:[art],paperCandidates:pairing==='PP'&&phase==='capture'?[p]:[],paperReviewCases:pairing==='PP'&&phase==='review'?[{...paperReview,completionId:id(30)}]:[],hybridCandidates:pairing==='PD'&&phase==='capture'?[hybrid]:[],hybridReviewCases:pairing==='PD'&&phase==='review'?[{...hybridReview,caseId:id(31)}]:[]};
}
export function receipt(actor,gameId,phase,body,result){return{kind:'synthetic-mixed-receipt-v1',actorId:actor,tournamentId:tid,eventId:eid,gameId,phase,idempotencyKey:body.idempotencyKey,request:body,result};}
